compile.workshop:
variables {
    global:
        0: g
        1: h
}

rule ("true condition") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
    }
}

rule ("literal true") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
    }
}

rule ("true with live") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.g > 1;
    }
    actions {
        Set Global Variable(h, 1);
    }
}

rule ("live then true then live") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.g > 1;
        Global.h > 1;
    }
    actions {
        Set Global Variable(h, 2);
    }
}

rule ("several true") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 4);
    }
}

rule ("live") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.g == 3;
    }
    actions {
        Set Global Variable(g, 5);
    }
}

rule ("and with true") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.g > 1;
    }
    actions {
        Set Global Variable(g, 6);
    }
}

rule ("or with true") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 7);
    }
}

rule ("negated false") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 8);
    }
}

disabled rule ("disabled true") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 9);
    }
}

rule ("delimiter true") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 10);
    }
}

rule ("delimiter false") {
    event {
        Ongoing - Global;
    }
    conditions {
        False != False;
    }
    actions {
        Set Global Variable(g, 11);
    }
}

